<script setup>
import {computed,ref,watch,onMounted} from 'vue';
import {useRoute} from 'vue-router';
import {FileText,Plus,Printer,Download} from '@lucide/vue';
import {useStore} from '../../store';
import {useCompanyData} from '../../store/companyData';
import {contractsApi,fromContractDto} from '../../api/contracts';
import {attestations} from '../../attestations/state';
import {companySettings,visibleRequests,requestForSelf,requestByRh,changeStatus,prepareAttestation,generateAttestation,exportSnapshot,STATUS,today,dateFR,contractSituation} from '../../attestations/model';
import {attestationPdf,downloadPdf,printAttestation} from '../../attestations/pdf';
import PageHeader from '../../components/ui/PageHeader.vue';
import Field from '../../components/ui/Field.vue';
import Badge from '../../components/ui/Badge.vue';
import Modal from '../../components/ui/Modal.vue';
import AttestationPreview from './AttestationPreview.vue';
const props=defineProps({selfOnly:Boolean});
const route=useRoute(),store=useStore(),data=useCompanyData();
const manage=computed(()=>!props.selfOnly&&store.can('attestations.traiter'));
const ctx=computed(()=>({companyId:store.companyId,employeeId:store.currentUser.id,name:`${store.currentUser.firstName||''} ${store.currentUser.lastName||''}`.trim(),can:p=>store.can(p)}));
const settings=computed(()=>companySettings(attestations,store.companyId));
const employeeScope=ref('all');
const eligibleEmployees=computed(()=>data.employees.filter(e=>employeeScope.value!=='former'||e.status==='inactif'));
const status=ref(''),error=ref(''),busy=ref(false),loading=ref(false),comment=ref(''),requestOpen=ref(false),directOpen=ref(false),employeeId=ref(''),selectedId=ref(''),contracts=ref([]),contractsError=ref(''),contractId=ref(''),date=ref(today()),city=ref(''),position=ref(''),signerId=ref(''),reason=ref(''),previewOpen=ref(false);
const all=computed(()=>visibleRequests(attestations,ctx.value,props.selfOnly));
const rows=computed(()=>all.value.filter(r=>!status.value||r.status===status.value).filter(r=>!manage.value||!route.query.employe||r.employeeId===route.query.employe));
const selected=computed(()=>all.value.find(r=>r.id===selectedId.value));
const employee=computed(()=>data.employees.find(e=>e.id===selected.value?.employeeId));
const contract=computed(()=>contracts.value.find(c=>c.id===contractId.value));
const ownPending=computed(()=>all.value.some(r=>r.employeeId===ctx.value.employeeId&&r.status==='a_traiter'));
const preview=computed(()=>selected.value?.snapshot?{errors:[],snapshot:selected.value.snapshot}:prepareAttestation(settings.value,employee.value,contract.value,{date:date.value,city:city.value,position:position.value,signerId:signerId.value},data.company));
const simpleStatus=status=>({a_traiter:'Demandée',disponible:'Prête à remettre',remise:'Remise',refusee:'Refusée'})[status]||status;
const signerName=computed(()=>{const s=settings.value.signers.find(s=>s.id===signerId.value);return s?`${s.firstName} ${s.lastName} · ${s.position}`:'À choisir';});
const employeeName=id=>{const e=data.employees.find(e=>e.id===id);return e?`${e.firstName} ${e.lastName}`:'Employé';};
let loadSequence=0;
async function openRequest(r){const sequence=++loadSequence;error.value='';selectedId.value=r.id;reason.value='';previewOpen.value=false;if(!manage.value)return;if(!store.can('attestations.generer'))return;loading.value=true;contractsError.value='';contracts.value=[];contractId.value='';date.value=today();city.value=settings.value.city;signerId.value=settings.value.signerId;position.value=employee.value?.jobTitle||data.fn(employee.value?.functionId)?.name||'';try{const loaded=await contractsApi.list();if(sequence!==loadSequence||selectedId.value!==r.id||store.companyId!==r.companyId)return;contracts.value=loaded.map(fromContractDto).filter(c=>c.employeeId===r.employeeId);const current=contracts.value.filter(c=>contractSituation(c,date.value)==='current');if(current.length===1)contractId.value=current[0].id;else if(contracts.value.length===1)contractId.value=contracts.value[0].id;}catch(e){contractsError.value='Contrats non chargés : '+e.message;}finally{if(sequence===loadSequence)loading.value=false;}}
function ask(){error.value='';try{requestForSelf(attestations,comment.value,ctx.value);requestOpen.value=false;comment.value='';store.toast('Demande d’attestation envoyée à RH.');}catch(e){error.value=e.message;}}
function direct(){error.value='';try{const r=requestByRh(attestations,data.employee(employeeId.value),ctx.value);directOpen.value=false;openRequest(r);}catch(e){error.value=e.message;}}
function transition(next){error.value='';try{changeStatus(attestations,selectedId.value,next,reason.value,ctx.value);store.toast('Demande mise à jour.');}catch(e){error.value=e.message;}}
function generate(){error.value='';try{generateAttestation(attestations,selectedId.value,settings.value,employee.value,contract.value,{date:date.value,city:city.value,position:position.value,signerId:signerId.value},data.company,ctx.value);previewOpen.value=false;store.toast('Attestation générée. Les informations sont conservées dans cette version.');}catch(e){error.value=e.message;}}
async function output(kind){if(!manage.value)return;error.value='';busy.value=true;try{const s=exportSnapshot(attestations,selectedId.value,ctx.value,kind);if(kind==='pdf')downloadPdf(await attestationPdf(s),s.reference);else printAttestation(s);}catch(e){error.value=e.message+' Pour un caractère non pris en charge par le PDF, utilisez l’impression du navigateur.';}finally{busy.value=false;}}
watch(()=>props.selfOnly,()=>{selectedId.value='';previewOpen.value=false;error.value='';requestOpen.value=false;directOpen.value=false;});
watch(()=>store.companyId,()=>{loadSequence++;selectedId.value='';contracts.value=[];status.value='';requestOpen.value=false;directOpen.value=false;error.value='';});
onMounted(()=>{if(!settings.value.legalName)settings.value.legalName=data.company.legalName||data.company.name;if(manage.value&&route.query.employe&&store.can('attestations.generer')){employeeId.value=String(route.query.employe);if(route.query.nouvelle==='1')directOpen.value=true;}});
</script>
<template><div class="att-page">
<PageHeader :title="manage?'Attestations de travail':'Mes attestations de travail'" :subtitle="manage?'Un parcours simple pour préparer et remettre un document.':'Demandez votre attestation, puis suivez sa préparation.'"><template #icon><FileText :size="18"/></template><template #actions><button v-if="manage&&!selected&&store.can('attestations.generer')" class="btn btn-primary" @click="employeeScope='all';employeeId=route.query.employe||'';directOpen=true;error='' "><Plus :size="15"/>Préparer pour un employé</button><button v-if="!manage&&store.can('attestations.demander')" class="btn btn-primary" :disabled="ownPending||!settings.active||!ctx.employeeId" @click="requestOpen=true;error=''">Demander mon attestation</button></template></PageHeader>
<div class="att-page-body">
 <div v-if="!selected" class="process-intro"><div><b>1. Demande</b><span>L’employé demande son attestation.</span></div><span class="arrow">→</span><div><b>2. Document prêt</b><span>RH vérifie et confirme le document.</span></div><span class="arrow">→</span><div><b>3. Remise</b><span>Le document est imprimé, signé et remis.</span></div></div>
 <p v-if="!manage&&ownPending" class="att-info">Votre demande est envoyée. RH s’occupe de la préparation. Vous n’avez rien d’autre à remplir.</p>
 <p v-if="!settings.active" class="att-info">Les nouvelles attestations sont désactivées pour cette société.</p>
 <template v-if="!selected">
  <div v-if="manage" class="list-tools"><Field v-slot="{id}" label="Afficher"><select :id="id" v-model="status"><option value="">Toutes les demandes</option><option v-for="(label,key) in STATUS" :key="key" :value="key">{{label}}</option></select></Field><details v-if="store.can('modeles_documents.consulter')"><summary>Paramétrage du document</summary><p>À faire une fois pour la société, puis à modifier au besoin.</p><a href="/parametres/modeles-documents">Personnaliser les deux modèles</a></details></div>
  <p v-if="manage&&route.query.employe" class="small text-muted">Dossier : {{employeeName(route.query.employe)}} · <a href="/documents-rh">Voir tous les employés</a></p>
  <div class="table-wrap"><table class="table"><thead><tr><th v-if="manage">Employé</th><th>Demandée le</th><th>Suivi</th><th></th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td v-if="manage">{{employeeName(r.employeeId)}}</td><td>{{new Date(r.requestedAt).toLocaleDateString('fr-FR')}}</td><td><Badge :tone="['disponible','remise'].includes(r.status)?'success':r.status==='refusee'?'danger':'neutral'">{{simpleStatus(r.status)}}</Badge></td><td><button class="btn btn-ghost btn-sm" @click="openRequest(r)">{{manage?(r.status==='a_traiter'?'Préparer':r.status==='disponible'?'Remettre':'Consulter'):'Voir le suivi'}}</button></td></tr><tr v-if="!rows.length"><td :colspan="manage?4:3">{{manage?'Aucune demande. Vous pouvez aussi préparer directement une attestation pour un employé.':'Aucune demande. Cliquez sur « Demander mon attestation ».'}}</td></tr></tbody></table></div>
 </template>
 <section v-if="selected" class="att-detail">
  <button class="btn btn-ghost btn-sm" @click="selectedId='';error=''">← Retour aux demandes</button>
  <div class="att-detail-heading"><h2>{{manage?employeeName(selected.employeeId):'Mon attestation de travail'}}</h2><Badge>{{simpleStatus(selected.status)}}</Badge></div>
  <p v-if="selected.comment&&selected.comment!=='Création directe par RH'" class="small text-muted">{{selected.comment}}</p>
  <p v-if="selected.reason" class="att-info"><strong>Motif du refus :</strong> {{selected.reason}}</p>
  <template v-if="manage&&selected.status!=='refusee'">
   <ol class="steps" aria-label="Suivi de la demande"><li :class="{active:!selected.snapshot,done:!!selected.snapshot}"><b>1</b> Demandée</li><li :class="{active:selected.status==='disponible',done:selected.status==='remise'}"><b>2</b> Prête à remettre</li><li :class="{active:selected.status==='remise'}"><b>3</b> Remise</li></ol>
   <template v-if="!selected.snapshot&&store.can('attestations.generer')">
    <div class="editing-heading"><div><h3>Vérifiez ou modifiez les informations</h3><p class="small text-muted">Le document s’actualise pendant la saisie. Vous pouvez aussi travailler sans aperçu.</p></div><button class="btn btn-ghost" :aria-pressed="previewOpen" @click="previewOpen=!previewOpen">{{previewOpen?'Masquer le document':'Afficher le document'}}</button></div>
    <div class="editing-workspace" :class="{'with-preview':previewOpen}">
     <div class="editing-form">
      <p v-if="loading" role="status">Chargement des contrats…</p><p v-if="contractsError" class="field-error">{{contractsError}}</p>
      <div class="form-grid"><Field v-slot="{id}" label="Contrat à attester" required><select :id="id" v-model="contractId"><option value="">Choisir un contrat…</option><option v-for="c in contracts" :key="c.id" :value="c.id">{{c.typeName}} · {{dateFR(c.start)}} → {{c.end?dateFR(c.end):'Sans fin'}} · {{({current:'En cours',ended:'Terminé',future:'À venir',suspended:'Suspendu',inactive:'Inactif'})[contractSituation(c,date)]}}</option></select></Field><Field v-slot="{id}" label="Date de l’attestation" required><input :id="id" v-model="date" type="date" :max="today()"/></Field>
      <Field v-slot="{id}" label="Fonction de l’employé" required><input :id="id" v-model="position" maxlength="150"/></Field><Field v-slot="{id}" label="Lieu de délivrance" required><input :id="id" v-model="city" maxlength="100"/></Field><Field v-slot="{id}" label="Signataire" required class="span-2"><select :id="id" v-model="signerId"><option v-for="s in settings.signers.filter(s=>s.active)" :key="s.id" :value="s.id">{{s.firstName}} {{s.lastName}} · {{s.position}}</option></select></Field></div>
      <p v-if="contract" class="small text-muted">Texte choisi : {{contractSituation(contract,date)==='ended'?'contrat terminé · du '+dateFR(contract.start)+' au '+dateFR(contract.end):contractSituation(contract,date)==='current'?'contrat en cours · depuis le '+dateFR(contract.start):'contrat à vérifier'}}.</p>
      <details class="secondary"><summary>Identité et informations du dossier</summary><p>{{employee?.firstName}} {{employee?.lastName}} · CIN {{employee?.cin||'manquante'}} · délivrée le {{employee?.cinIssueDate?dateFR(employee.cinIssueDate):'non renseignée'}}</p><p class="small text-muted">L’identité et les dates du contrat proviennent du dossier employé.</p><a v-if="store.can('employes.modifier')" :href="`/employes/${employee?.id}`">Corriger le dossier employé</a></details>
      <div v-if="preview.errors.length&&!loading" class="field-error"><p v-for="(e,index) in preview.errors" :key="index">{{e}}</p><a v-if="store.can('employes.modifier')" :href="`/employes/${employee?.id}`">Compléter la fiche employé</a><p v-if="store.can('modeles_documents.modifier')"><a href="/parametres/modeles-documents">Compléter les informations de la société</a></p></div>
     </div>
     <div v-if="previewOpen" class="live-document"><AttestationPreview v-if="preview.snapshot" :snapshot="preview.snapshot"/><p v-else class="att-info">Complétez les informations indiquées pour afficher le document.</p></div>
    </div>
    <div class="att-actions"><button class="btn btn-primary" :disabled="!!preview.errors.length||loading" @click="generate">Confirmer et rendre prête à remettre</button></div>
   </template>
   <p v-else-if="!selected.snapshot" class="att-info">La préparation est réservée aux utilisateurs autorisés à générer les attestations.</p>
   <div v-if="selected.snapshot" class="delivery">
    <h3>{{selected.status==='remise'?'Attestation remise':'Votre document est prêt'}}</h3>
    <p>{{selected.status==='remise'?'Le traitement est terminé. Le document reste consultable.':'Téléchargez ou imprimez le document, faites-le signer, puis remettez-le à l’employé.'}}</p>
    <div v-if="store.can('attestations.imprimer')" class="att-actions"><button class="btn btn-primary" :disabled="busy" @click="output('pdf')"><Download :size="15"/>Télécharger le PDF</button><button class="btn btn-ghost" :disabled="busy" @click="output('print')"><Printer :size="15"/>Imprimer</button></div>
    <p v-else class="small text-muted">Le téléchargement et l’impression sont réservés aux utilisateurs habilités.</p>
    <div v-if="selected.status==='disponible'" class="handover"><strong>Après signature et remise au salarié</strong><button class="btn btn-ghost" @click="transition('remise')">Confirmer la remise à l’employé</button></div>
    <details class="secondary"><summary>Voir le document enregistré</summary><AttestationPreview :snapshot="selected.snapshot"/></details>
   </div>
  </template>
  <template v-else-if="!manage"><div class="employee-status"><h3>{{simpleStatus(selected.status)}}</h3><p>{{({a_traiter:'Votre demande a été reçue. RH va préparer votre attestation.',disponible:'Votre attestation est prête. Contactez RH pour récupérer le document signé.',remise:'RH a confirmé la remise de votre attestation.',refusee:'Votre demande a été refusée. Le motif est indiqué ci-dessus.'})[selected.status]}}</p></div></template>
  <details v-if="manage&&selected.status==='a_traiter'" class="secondary"><summary>Autre action : refuser la demande</summary><Field v-slot="{id}" label="Motif du refus" required><textarea :id="id" v-model="reason" rows="2" maxlength="1000"/></Field><button class="btn btn-ghost" @click="transition('refusee')">Confirmer le refus</button></details>
  <details class="secondary"><summary>Historique · {{selected.id}}</summary><p v-for="(h,index) in selected.history" :key="index" class="small">{{new Date(h.at).toLocaleString('fr-FR')}} · {{h.actor}} · {{h.action}}</p></details>
 </section>
 <p v-if="error" class="field-error" role="alert">{{error}}</p>
</div>
<Modal :open="requestOpen" title="Demander mon attestation" @close="requestOpen=false"><p>Pour <strong>{{ctx.name}}</strong>. RH s’occupe du contrat, du document et de la signature.</p><Field v-slot="{id}" label="Un message pour RH ? (facultatif)"><textarea :id="id" v-model="comment" rows="2" maxlength="1000"/></Field><p v-if="error" class="field-error" role="alert">{{error}}</p><template #footer><button class="btn btn-ghost" @click="requestOpen=false">Annuler</button><button class="btn btn-primary" @click="ask">Envoyer ma demande</button></template></Modal>
<Modal :open="directOpen&&manage" title="Pour quel employé ?" @close="directOpen=false"><p class="small text-muted">Vous pouvez établir une attestation pour un employé actuel ou un ancien salarié, même sans contrat en cours.</p><Field v-slot="{id}" label="Afficher les employés"><select :id="id" v-model="employeeScope" @change="employeeId=''"><option value="all">Tous, y compris les anciens salariés</option><option value="former">Anciens salariés / employés inactifs</option></select></Field><Field v-slot="{id}" label="Employé" required><select :id="id" v-model="employeeId"><option value="">Choisir un employé…</option><option v-for="e in eligibleEmployees" :key="e.id" :value="e.id">{{e.firstName}} {{e.lastName}}{{e.status==='inactif'?' · '+(e.statusValue||'Inactif'):''}}</option></select></Field><p class="small text-muted">Vous allez vérifier les informations, puis voir le document.</p><p v-if="error" class="field-error" role="alert">{{error}}</p><template #footer><button class="btn btn-ghost" @click="directOpen=false">Annuler</button><button class="btn btn-primary" :disabled="!employeeId" @click="direct">Continuer →</button></template></Modal>
</div></template>
<style scoped>
.editing-heading{display:flex;justify-content:space-between;align-items:center;gap:15px;margin:18px 0}.editing-heading h3{margin:0}.editing-heading p{margin:4px 0}.editing-workspace.with-preview{display:grid;grid-template-columns:minmax(230px,300px) minmax(0,1fr);gap:24px;align-items:start}.with-preview .form-grid{grid-template-columns:1fr}.with-preview .span-2{grid-column:auto}.live-document{min-width:0;overflow:auto}.live-document :deep(.att-paper){min-height:700px;margin:0;padding:32px 24px}.live-document :deep(.layout-block){font-size:12px!important}.live-document :deep(.att-paper-body){font-size:12px}.live-document :deep(h2){font-size:18px}.live-document :deep(header){min-height:50px}.live-document :deep(.att-paper-sign){margin-top:35px}@media(max-width:800px){.editing-workspace.with-preview{grid-template-columns:1fr}.editing-heading{align-items:start;flex-direction:column}}.att-page-body{padding:0 24px 30px;font-size:13px;line-height:1.7}.process-intro{display:flex;gap:20px;align-items:center;padding:20px;margin:12px 0 24px;border:1px solid #dbe5f1;background:#f7faff;border-radius:10px}.process-intro>div{flex:1}.process-intro b,.process-intro span:not(.arrow){display:block}.process-intro span{font-size:12px;color:#64748b}.arrow{color:#5981b4;font-size:22px}.list-tools{display:flex;align-items:center;justify-content:space-between;gap:20px;margin:20px 0}.list-tools>div{max-width:250px;flex:1}.list-tools details{max-width:300px}.att-detail{border:1px solid var(--border);border-radius:10px;padding:22px;margin-top:16px}.att-detail-heading{display:flex;justify-content:space-between;gap:15px;align-items:center;flex-wrap:wrap;margin:16px 0}.att-detail h2{font-size:19px}.att-detail h3{font-size:16px;margin:22px 0 8px}.steps{list-style:none;display:flex;padding:0;margin:24px 0 28px;gap:8px}.steps li{flex:1;padding:12px;background:#f2f5f9;border-radius:8px;color:#708096;font-size:12px}.steps b{display:inline-grid;place-items:center;width:24px;height:24px;border-radius:50%;background:white;margin-right:6px}.steps .active{background:#e8f1ff;color:#1e58a3;box-shadow:inset 0 0 0 1px #99bce9;font-weight:600}.steps .done{color:#177464;background:#edf8f4}.recap{display:grid;gap:6px;background:#f5f8fc;padding:16px;border-radius:8px;margin:20px 0}.recap span{font-size:12px;color:#536781}.att-info,.employee-status{background:var(--primary-soft);padding:16px;margin:18px 0;border-radius:8px}.att-actions{display:flex;flex-wrap:wrap;gap:10px;margin:22px 0}.secondary{border-top:1px solid var(--border);padding-top:15px;margin-top:22px}.secondary .form-grid{margin-top:18px}.handover{display:flex;align-items:center;justify-content:space-between;gap:15px;padding:18px;background:#f2f8f5;border-radius:8px;margin:24px 0}summary{cursor:pointer;color:var(--primary);font-size:12px;font-weight:600}.field-error p{margin:6px 0}@media(max-width:650px){.process-intro,.steps,.handover{flex-direction:column;align-items:stretch}.arrow{display:none}.list-tools{align-items:start;flex-direction:column}}
</style>
